  if(page=="pick"){Pick(grade){grade=it;p.edit().putInt("grade",it).apply();page="home"};return@MaterialTheme}
  Scaffold(topBar={CenterAlignedTopAppBar(title={Text("Narendar Hub",fontWeight=FontWeight.Black)})},bottomBar={NavigationBar{listOf("home" to "⌂","learn" to "▣","quiz" to "✓","library" to "▤","profile" to "●").forEach{(k,ic)->NavigationBarItem(page==k,{page=k},icon={Text(ic)},label={Text(k.replaceFirstChar{it.uppercase()})})}}}){pad->
   Box(Modifier.fillMaxSize().padding(pad)){AnimatedContent(page,label="page"){s->when(s){"home"->Home(grade,xp,correct,tried,tasks.count{!it.done},notes.size){page=it};"learn"->Learn(grade){page="quiz"};"quiz"->Quiz(grade,::record){toast=it};"library"->Library(notes,tasks,::saveNotes,::saveTasks);"profile"->Profile(grade,xp,correct,tried,dark,{dark=it;p.edit().putBoolean("dark",it).apply()}){grade=-1;p.edit().putInt("grade",-1).apply();page="pick"}}};AnimatedVisibility(toast.isNotEmpty(),enter=slideInVertically{it}+fadeIn(),exit=fadeOut(),modifier=Modifier.align(Alignment.BottomCenter).padding(8.dp)){Surface(shape=RoundedCornerShape(18.dp),tonalElevation=8.dp){Text(toast,Modifier.padding(14.dp),fontWeight=FontWeight.Bold)}}}
  }
 }
