private fun test(maxG:Int,s:String,d:String,size:Int,seed:Int):List<M>{val ds=if(d=="Mixed")listOf("Easy","Medium","Hard")else listOf(d);val all=ArrayList<M>();for(g in 1..maxG)for(x in ds)all.addAll(bank(g,s,x,2500));return all.shuffled(kotlin.random.Random(seed*7919+s.hashCode())).take(size)}
private fun bank(g:Int,s:String,d:String,n:Int):List<M>{val a=ArrayList<M>(n);for(i in 0 until n)a.add(make(g,s,d,i));return a}
private fun make(g:Int,s:String,d:String,i:Int):M{val n=i+1;val b=i+g*37+when(d){"Easy"->11;"Medium"->101;else->1001};val topic=when(s){"Mathematics"->listOf("Arithmetic","Fractions","Algebra","Geometry","Patterns")[i%5];"Science"->listOf("Matter","Life","Energy","Earth","Forces")[i%5];"English"->listOf("Grammar","Vocabulary","Tenses","Reading","Writing")[i%5];"Computer Science"->listOf("Hardware","Software","Programming","Networks","Cyber Safety")[i%5];"SST"->listOf("History","Geography","Civics","Economics","Society")[i%5];"Urdu"->listOf("قواعد","الفاظ","مطالعہ","ادب","تحریر")[i%5];"Physics"->listOf("Motion","Energy","Waves","Electricity","Forces")[i%5];"Chemistry"->listOf("Atoms","Matter","Reactions","Solutions","Elements")[i%5];else->listOf("Cells","Plants","Animals","Genetics","Ecology")[i%5]};if(s=="Mathematics")return math(g,d,topic,n,b);val set=mapOf("Science" to listOf("evaporation","photosynthesis","gravity","condensation","friction","ecosystem","reflection","magnetism"),"English" to listOf("quickly","beautiful","because","carefully","although","honest","between","however"),"Computer Science" to listOf("CPU","RAM","browser","algorithm","firewall","compiler","keyboard","router"),"SST" to listOf("map","constitution","river","trade","community","citizen","climate","culture"),"Urdu" to listOf("اسم","فعل","صفت","جملہ","محاورہ","کہانی","شاعر","مضمون"),"Physics" to listOf("velocity","force","energy","frequency","voltage","current","mass","pressure"),"Chemistry" to listOf("atom","molecule","element","mixture","reaction","solution","electron","acid"),"Biology" to listOf("cell","root","organ","gene","ecosystem","chlorophyll","tissue","habitat"))[s]?:emptyList();val c=set[b%set.size];val opts=listOf(c,set[(b+1)%set.size],set[(b+3)%set.size],set[(b+5)%set.size]);val prompt=listOf("Which $s concept best matches $topic?","Choose the most accurate $s term for Class $g.","Which option correctly describes this Class $g $s idea?","Select the best answer for this $topic exercise.")[b%4];return M(g*10000+n,g,s,d,topic,"$prompt Set #$n",opts,0,"The correct answer is $c. Review the definition of $topic and compare the alternatives.")}
private fun math(g:Int,d:String,t:String,n:Int,b:Int):M{val mode=n%8;val a=b%89+g;val x=b*3%47+2;val ans=when(mode){0->a+x;1->a*x;2->abs(a-x);3->(a+x)%10;4->a+x+5;5->a*x+3;6->abs(a-x)+2;else->a*x%17};val q=when(mode){0->"Class $g Mathematics: calculate $a + $x. Set #$n";1->"Class $g Mathematics: calculate $a × $x. Set #$n";2->"Class $g Mathematics: find the positive difference of $a and $x. Set #$n";3->"Class $g Mathematics: find the remainder of ${a+x} ÷ 10. Set #$n";4->"Class $g Mathematics: $a increases by ${x+5}. What is the result? Set #$n";5->"Class $g Mathematics: multiply $a by $x, then add 3. Set #$n";6->"Class $g Mathematics: what is |$a − $x| + 2? Set #$n";else->"Class $g Mathematics: what is the remainder of ${a*x} ÷ 17? Set #$n"};return M(g*10000+n,g,"Mathematics",d,t,q,listOf(ans.toString(),(ans+1).toString(),(if(ans>1)ans-1 else ans+2).toString(),(ans+3).toString()),0,"Solve the operation carefully. The correct result is $ans.")}
private fun loadNotes(p:android.content.SharedPreferences):List<Note>{return try{val a=JSONArray(p.getString("notes","[]"));List(a.length()){val o=a.getJSONObject(it);Note(o.getLong("id"),o.getString("title"),o.getString("body"))}}catch(_:Exception){emptyList()}}
private fun loadTasks(p:android.content.SharedPreferences):List<Task>{return try{val a=JSONArray(p.getString("tasks","[]"));List(a.length()){val o=a.getJSONObject(it);Task(o.getLong("id"),o.getString("text"),o.getBoolean("done"))}}catch(_:Exception){emptyList()}}
private fun notesJson(v:List<Note>)=JSONArray().apply{v.forEach{put(JSONObject().apply{put("id",it.id);put("title",it.title);put("body",it.body)})}}.toString()
private fun tasksJson(v:List<Task>)=JSONArray().apply{v.forEach{put(JSONObject().apply{put("id",it.id);put("text",it.text);put("done",it.done)})}}.toString()
